-- ============================================================
-- SEED MASTER DATA: 1 Perusahaan + 25 Site + 155 Unit (DUMMY)
-- Jalankan di Supabase SQL Editor. Ganti nilai yang ditandai
-- 'GANTI' dengan data REAL sebelum run. Aman diulang.
-- ============================================================

BEGIN;

-- Bersihkan data dummy pola UUID unit/site dulu (agar bisa diulang).
-- CATATAN: customer TIDAK dihapus - ada FK users.customer_id ON DELETE
-- SET NULL, jadi menghapus customer akan memutus relasi akun (customer_id NULL).
-- Customer di-upsert (ON CONFLICT) di bawah.
DELETE FROM units WHERE id::text LIKE '31111111-%';
DELETE FROM sites WHERE id::text LIKE '21111111-%';

-- ============================================================
-- 1. PERUSAHAAN (1 baris)  -- GANTI name, code, pic_name, pic_phone
--    Upsert: tidak menghapus customer agar users.customer_id aman.
-- ============================================================
  '11111111-1111-1111-1111-111111111111',
  'ASDP',          -- GANTI: nama perusahaan
  '33333',                  -- GANTI: kode unik perusahaan (dipakai registrasi)
  'Pak Yoga',      -- GANTI: nama PIC perusahaan
  '+62 857-1128-5864',              -- GANTI: no telp PIC perusahaan
  false
)
ON CONFLICT (id) DO UPDATE SET
  name       = EXCLUDED.name,
  code       = EXCLUDED.code,
  pic_name   = EXCLUDED.pic_name,
  pic_phone  = EXCLUDED.pic_phone,
  is_deleted = EXCLUDED.is_deleted;

-- ============================================================
-- 2. SITE (24 baris)     -- GANTI nama site real; pic_name/pic_phone dummy
-- ============================================================

-- ============================================================
-- 3. UNIT (150 baris, NAMA RUANGAN)  -- GANTI nama ruangan real
-- ============================================================

COMMIT;

